-- civgraph records database: tables added in migration 0003 (generated by scripts/records/schema.mjs --sql 3).



CREATE TABLE maps (
  map_id TEXT NOT NULL,
  slug TEXT,
  name TEXT,
  category TEXT,
  date TEXT,
  hidden INTEGER,
  featured INTEGER,
  is_group INTEGER,
  parent_id TEXT,
  ord INTEGER NOT NULL,
  record TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (map_id)
);
CREATE INDEX maps_ord ON maps(ord, map_id);
CREATE INDEX maps_slug ON maps(slug);
CREATE INDEX maps_category ON maps(category, ord);

CREATE TABLE catalogue_parts (
  key TEXT NOT NULL,
  ord INTEGER NOT NULL,
  value TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (key)
);

CREATE TABLE layers (
  layer_id TEXT NOT NULL,
  map_id TEXT,
  kind TEXT,
  alias_of TEXT,
  ord INTEGER NOT NULL,
  record TEXT NOT NULL,
  duplicates TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (layer_id)
);
CREATE INDEX layers_ord ON layers(ord, layer_id);
CREATE INDEX layers_map ON layers(map_id, ord);

CREATE TABLE layer_parts (
  key TEXT NOT NULL,
  ord INTEGER NOT NULL,
  value TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (key)
);

CREATE TABLE layer_aliases (
  alias TEXT NOT NULL,
  layer_id TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (alias)
);

CREATE TABLE map_cards (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  detail TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX map_cards_ord ON map_cards(ord, slug);
CREATE INDEX map_cards_id ON map_cards(id);

CREATE TABLE feature_groups (
  ord INTEGER NOT NULL,
  id TEXT,
  card TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (ord)
);

CREATE TABLE document_parts (
  name TEXT NOT NULL,
  part INTEGER NOT NULL,
  body TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (name, part)
);

